import {zipSync} from 'fflate';import {readdir,readFile,writeFile} from 'node:fs/promises';import {join} from 'node:path';const root=process.env.SUKOAA_LARAVEL_SOURCE||'examples/browser-laravel',files={};async function walk(dir,prefix=''){for(const e of await readdir(dir,{withFileTypes:true})){if(['.git','tests','.env'].includes(e.name))continue;const n=prefix+e.name;if(e.isDirectory())await walk(join(dir,e.name),n+'/');else if(e.isFile())files[n]=new Uint8Array(await readFile(join(dir,e.name)));}}await readFile(root+'/vendor/autoload.php');await walk(root);await writeFile('public/runtime/backend/laravel.zip',zipSync(files,{level:9}));console.log('Prepared the locked Laravel browser bundle.');
